unsigned int fd_val = 3;
unsigned long off_H = 0x1;
unsigned long off_L = 0x00000000;
loff_t new_pos_64;
unsigned int seek_mode = 0; /* SEEK_SET */

/* Reposition file offset (64-bit) */
long ret = _llseek(
    fd_val,
    off_H,
    off_L,
    &new_pos_64,
    seek_mode
);
